-- Generated by tools/build_quest_data.py; references are not eligibility or a walkthrough.
return {["scripts/zones/Windurst_Waters/npcs/Leepe-Hoppe.lua"]={["Path"]="scripts/zones/Windurst_Waters/npcs/Leepe-Hoppe.lua",["SHA256"]="f5b8ef758bf5c037fcb789efbe97ac62e8e0430277c2096af3dde98a4838cccc",["Text"]="-----------------------------------\n-- Area: Windurst Waters\n--  NPC: Leepe-Hoppe\n-- Involved in Mission 1-3, Mission 7-2\n-- !pos 13 -9 -197 238\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if\n        npcUtil.tradeHasExactly(trade, { 1696, 1697, 1698 }) and -- Magicked Steel Ingot, Spruce Lumber, Extra-fine File\n        player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.TUNING_IN) == xi.questStatus.QUEST_ACCEPTED\n    then\n        player:startEvent(886)\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local tuningIn = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.TUNING_IN)\n    local tuningOut = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.TUNING_OUT)\n\n    -- Tuning In\n    if\n        tuningIn == xi.questStatus.QUEST_AVAILABLE and\n        player:getFameLevel(xi.fameArea.WINDURST) >= 4 and\n        (player:getCurrentMission(xi.mission.log_id.COP) >= xi.mission.id.cop.DISTANT_BELIEFS or player:hasCompletedMission(xi.mission.log_id.COP, xi.mission.id.cop.THE_LAST_VERSE))\n    then\n        player:startEvent(884, 0, 1696, 1697, 1698) -- Magicked Steel Ingot, Spruce Lumber, Extra-fine File\n\n    -- Tuning Out\n    elseif\n        tuningIn == xi.questStatus.QUEST_COMPLETED and\n        tuningOut == xi.questStatus.QUEST_AVAILABLE\n    then\n        player:startEvent(888) -- Starting dialogue\n\n    elseif\n        tuningOut == xi.questStatus.QUEST_ACCEPTED and\n        player:getCharVar('TuningOut_Progress') == 8\n    then\n        player:startEvent(897) -- Finishing dialogue\n\n    elseif tuningIn == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(885, 0, 1696, 1697, 1698) -- Reminder to bring Magicked Steel Ingot, Spruce Lumber, Extra-fine File\n    elseif tuningOut == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(889) -- Reminder to go help Ildy in Kazham\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    -- Tuning In\n    if csid == 884 then\n        player:addQuest(xi.questLog.WINDURST, xi.quest.id.windurst.TUNING_IN)\n\n    elseif\n        csid == 886 and\n        npcUtil.completeQuest(player, xi.questLog.WINDURST, xi.quest.id.windurst.TUNING_IN, {\n            gil = 4000,\n            title = xi.title.FINE_TUNER,\n        })\n    then\n        player:tradeComplete()\n\n    -- Tuning Out\n    elseif csid == 888 then\n        player:setCharVar('TuningOut_Progress', 1)\n        player:addQuest(xi.questLog.WINDURST, xi.quest.id.windurst.TUNING_OUT)\n\n    elseif\n        csid == 897 and\n        npcUtil.completeQuest(player, xi.questLog.WINDURST, xi.quest.id.windurst.TUNING_OUT, {\n            item = xi.item.CACHE_NEZ, -- Cache-Nez\n            title = xi.title.FRIEND_OF_THE_HELMED,\n            fame = 40,\n            fameArea = xi.fameArea.WINDURST,\n        })\n    then\n        player:setCharVar('TuningOut_Progress', 0) -- zero when quest is done\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Waters/npcs/Mashuu-Ajuu.lua"]={["Path"]="scripts/zones/Windurst_Waters/npcs/Mashuu-Ajuu.lua",["SHA256"]="623cd1a060015663310469c4864d1dd0cb71b6af6f8d1250e48c839c9100dd38",["Text"]="-----------------------------------\n-- Area: Windurst Waters\n--  NPC: Mashuu-Ajuu\n-- Starts and Finished Quest: Reap What You Sow\n-- Involved in Quest: Making the Grade\n-- !pos 129 -6 167 238\n-----------------------------------\nlocal ID = zones[xi.zone.WINDURST_WATERS]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    local reapstatus = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.REAP_WHAT_YOU_SOW)\n    if reapstatus >= 1 and trade:getItemCount() == 1 and trade:getGil() == 0 then\n        if trade:hasItemQty(xi.item.SOBBING_FUNGUS, 1) then\n            player:startEvent(475, 500, xi.item.STATIONERY_SET)                     -- REAP WHAT YOU SOW + GIL: Quest Turn In: Sobbing Fungus turned in\n        elseif trade:hasItemQty(xi.item.DEATHBALL, 1) then\n            player:startEvent(477, 700)                     -- REAP WHAT YOU SOW + GIL + Stationary Set: Deathball turned in\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local reapstatus = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.REAP_WHAT_YOU_SOW)\n\n    if reapstatus == xi.questStatus.QUEST_AVAILABLE then\n        local rand = math.randomInt(1, 2)\n        if rand == 1 then\n            player:startEvent(463, 0, xi.item.SOBBING_FUNGUS, xi.item.BAG_OF_HERB_SEEDS)                 -- REAP WHAT YOU SOW + HERB SEEDS: QUEST START\n        end\n    elseif reapstatus == xi.questStatus.QUEST_ACCEPTED then\n        local rand = math.randomInt(1, 2)\n        if rand == 1 then\n            player:startEvent(464, 0, xi.item.SOBBING_FUNGUS, xi.item.BAG_OF_HERB_SEEDS)                  -- REAP WHAT YOU SOW + HERB SEEDS: OBJECTIVE REMINDER\n        else\n            player:startEvent(476)                          -- Another Conversation During Quest\n        end\n    elseif reapstatus == xi.questStatus.QUEST_COMPLETED and player:needToZone() then\n        player:startEvent(478)                              -- REAP WHAT YOU SOW: After Quest\n    elseif\n        reapstatus == xi.questStatus.QUEST_COMPLETED and\n        not player:needToZone() and\n        player:getCharVar('QuestReapSow_var') == 0\n    then\n        local rand = math.randomInt(1, 2)\n        if rand == 1 then\n            player:startEvent(479, 0, xi.item.SOBBING_FUNGUS, xi.item.BAG_OF_HERB_SEEDS)                -- REAP WHAT YOU SOW + HERB SEEDS: REPEATABLE QUEST START\n        end\n    elseif\n        reapstatus == xi.questStatus.QUEST_COMPLETED and\n        player:getCharVar('QuestReapSow_var') == 1\n    then\n        local rand = math.randomInt(1, 2)\n        if rand == 1 then\n            player:startEvent(464, 0, xi.item.SOBBING_FUNGUS, xi.item.BAG_OF_HERB_SEEDS)                  -- REAP WHAT YOU SOW + HERB SEEDS: OBJECTIVE REMINDER\n        else\n            player:startEvent(476)                          -- Another Conversation During Quest\n        end\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if\n        ((csid == 463 and option == 3) or (csid == 479 and option == 3)) and\n        player:getFreeSlotsCount() == 0\n    then\n        -- REAP WHAT YOU SOW + HERB SEEDS: QUEST START - ACCEPTED - INVENTORY FULL\n        player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.BAG_OF_HERB_SEEDS)\n    elseif csid == 463 and option == 3 then                      -- REAP WHAT YOU SOW + HERB SEEDS: QUEST START - ACCEPTED\n        player:addQuest(xi.questLog.WINDURST, xi.quest.id.windurst.REAP_WHAT_YOU_SOW)\n        player:addItem(xi.item.BAG_OF_HERB_SEEDS)\n        player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.BAG_OF_HERB_SEEDS)\n    elseif\n        (csid == 475 or csid == 477) and\n        player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.REAP_WHAT_YOU_SOW) == xi.questStatus.QUEST_ACCEPTED and\n        player:getFreeSlotsCount() == 0\n    then\n        -- inventory full on quest turn in\n        player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.STATIONERY_SET)\n    elseif csid == 475 then                                -- REAP WHAT YOU SOW + 500 GIL: Quest Turn In: Sobbing Fungus turned in\n        player:addGil(xi.settings.main.GIL_RATE * 500)\n        player:tradeComplete()\n        player:needToZone(true)\n        if player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.REAP_WHAT_YOU_SOW) == xi.questStatus.QUEST_ACCEPTED then\n            player:completeQuest(xi.questLog.WINDURST, xi.quest.id.windurst.REAP_WHAT_YOU_SOW)\n            player:addFame(xi.fameArea.WINDURST, 10)\n            player:addItem(xi.item.STATIONERY_SET)\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.STATIONERY_SET)\n        elseif player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.REAP_WHAT_YOU_SOW) == xi.questStatus.QUEST_COMPLETED then\n            player:addFame(xi.fameArea.WINDURST, 10)\n            player:setCharVar('QuestReapSow_var', 0)\n        end\n    elseif csid == 477 then                                -- REAP WHAT YOU SOW + GIL + Stationary Set: Quest Turn In: Deathball turned in\n        player:addGil(xi.settings.main.GIL_RATE * 700)\n        player:tradeComplete()\n        player:needToZone(true)\n        if player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.REAP_WHAT_YOU_SOW) == xi.questStatus.QUEST_ACCEPTED then\n            player:completeQuest(xi.questLog.WINDURST, xi.quest.id.windurst.REAP_WHAT_YOU_SOW)\n            player:addFame(xi.fameArea.WINDURST, 10)\n            player:addItem(xi.item.STATIONERY_SET)\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.STATIONERY_SET)\n        elseif player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.REAP_WHAT_YOU_SOW) == xi.questStatus.QUEST_COMPLETED then\n            player:addFame(xi.fameArea.WINDURST, 10)\n            player:setCharVar('QuestReapSow_var', 0)\n        end\n    elseif csid == 479 and option == 3 then                 -- REAP WHAT YOU SOW + HERB SEEDS: REPEATABLE QUEST START - ACCEPTED\n        player:setCharVar('QuestReapSow_var', 1)\n        player:addItem(xi.item.BAG_OF_HERB_SEEDS)\n        player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.BAG_OF_HERB_SEEDS)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Waters/npcs/Maysoon.lua"]={["Path"]="scripts/zones/Windurst_Waters/npcs/Maysoon.lua",["SHA256"]="5ab1812718487ae7fccea9b6ee5f6196b117eb35994753120fb8255da4f2a4dd",["Text"]="-----------------------------------\n-- Area: Windurst Waters\n--  NPC: Maysoon\n-- Starts and Finishes Quest: Hoist the Jelly, Roger\n-- Involved in Quests: Cook's Pride\n-- !pos -105 -2 69 238\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.HOIST_THE_JELLY_ROGER) == xi.questStatus.QUEST_ACCEPTED then\n        if\n            trade:hasItemQty(xi.item.SERVING_OF_ROYAL_JELLY, 1) and\n            trade:getGil() == 0 and\n            trade:getItemCount() == 1\n        then\n            player:startEvent(10001) -- Finish quest \"Hoist the Jelly, Roger\"\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local cooksPride = player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.COOKS_PRIDE)\n    local hoistTheJelly = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.HOIST_THE_JELLY_ROGER)\n\n    if\n        cooksPride == xi.questStatus.QUEST_ACCEPTED and\n        hoistTheJelly == xi.questStatus.QUEST_AVAILABLE\n    then\n        player:startEvent(10000) -- Start quest \"Hoist the Jelly, Roger\"\n    else\n        player:startEvent(266) -- Standard dialog\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 10000 then\n        player:addQuest(xi.questLog.WINDURST, xi.quest.id.windurst.HOIST_THE_JELLY_ROGER)\n    elseif csid == 10001 then\n        player:completeQuest(xi.questLog.WINDURST, xi.quest.id.windurst.HOIST_THE_JELLY_ROGER)\n        npcUtil.giveKeyItem(player, xi.keyItem.SUPER_SOUP_POT)\n        player:addFame(xi.fameArea.WINDURST, 40)\n        player:tradeComplete()\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Waters/npcs/Naiko-Paneiko.lua"]={["Path"]="scripts/zones/Windurst_Waters/npcs/Naiko-Paneiko.lua",["SHA256"]="9e62ebfc952ab1a23b677472c91a6e3a88f41643cf183489d54369ff16b30fb2",["Text"]="-----------------------------------\n-- Area: Windurst Waters\n--  NPC: Naiko-Paneiko\n-- Involved In Quest: Making Headlines, Riding on the Clouds\n-- !pos -246 -5 -308 238\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local makingHeadlines = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.MAKING_HEADLINES)\n\n    if makingHeadlines == xi.questStatus.QUEST_AVAILABLE then\n        player:startEvent(665)\n    elseif makingHeadlines == xi.questStatus.QUEST_ACCEPTED then\n        -- bitmask of progress: 0 = Kyume-Romeh, 1 = Yuyuju, 2 = Hiwom-Gomoi, 3 = Umumu, 4 = Mahogany Door\n        local prog = player:getCharVar('QuestMakingHeadlines_var')\n\n        if not utils.mask.isFull(prog, 4) then\n            if math.randomInt(1, 100) <= 50 then\n                player:startEvent(666) -- Quest Reminder 1\n            else\n                player:startEvent(671) -- Quest Reminder 2\n            end\n        elseif not utils.mask.getBit(prog, 4) then\n            player:startEvent(673) -- Advises to validate story\n        else\n            if math.randomInt(1, 100) <= 50 then\n                player:startEvent(674) -- Quest finish 1\n            else\n                player:startEvent(670) -- Quest finish 2\n            end\n        end\n    else\n        player:startEvent(663) -- Standard conversation\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 665 then\n        player:addQuest(xi.questLog.WINDURST, xi.quest.id.windurst.MAKING_HEADLINES)\n    elseif csid == 670 or csid == 674 then\n        npcUtil.completeQuest(player, xi.questLog.WINDURST, xi.quest.id.windurst.MAKING_HEADLINES, {\n            title = xi.title.EDITORS_HATCHET_MAN,\n            gil = 560,\n            var = 'QuestMakingHeadlines_var',\n        })\n        player:delKeyItem(xi.keyItem.WINDURST_WOODS_SCOOP)\n        player:delKeyItem(xi.keyItem.WINDURST_WALLS_SCOOP)\n        player:delKeyItem(xi.keyItem.WINDURST_WATERS_SCOOP)\n        player:delKeyItem(xi.keyItem.PORT_WINDURST_SCOOP)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Waters/npcs/Ranpi-Monpi.lua"]={["Path"]="scripts/zones/Windurst_Waters/npcs/Ranpi-Monpi.lua",["SHA256"]="61a6059ce1e46b966455af3140fb734999fe18b96a852107c9481e96e78d466b",["Text"]="-----------------------------------\n-- Area: Windurst Waters\n--  NPC: Ranpi-Monpi\n-- Starts and Finishes Quest: A Crisis in the Making\n-- Involved in quest: In a Stew, For Want of a Pot, The Dawn of Delectability\n-- !pos -116 -3 52  238\n-- (outside the shop he is in)\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local crisisstatus = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.A_CRISIS_IN_THE_MAKING)\n\n    -- A Crisis in the Making\n    if\n        crisisstatus == xi.questStatus.QUEST_AVAILABLE and\n        player:getFameLevel(xi.fameArea.WINDURST) >= 2 and\n        not player:needToZone()\n    then\n        -- A Crisis in the Making + ITEM: Quest Offer\n        player:startEvent(258, 0, 625)\n    elseif crisisstatus == xi.questStatus.QUEST_ACCEPTED then\n        local prog = player:getCharVar('QuestCrisisMaking_var')\n        if prog == 1 then -- A Crisis in the Making: Quest Objective Reminder\n            player:startEvent(262, 0, 625)\n        elseif prog == 2 then -- A Crisis in the Making: Quest Finish\n            player:startEvent(267)\n        end\n    elseif\n        crisisstatus == xi.questStatus.QUEST_COMPLETED and\n        not player:needToZone() and\n        player:getCharVar('QuestCrisisMaking_var') == 0\n    then\n        -- A Crisis in the Making + ITEM: Repeatable Quest Offer\n        player:startEvent(259, 0, 625)\n    elseif\n        crisisstatus == xi.questStatus.QUEST_COMPLETED and\n        player:getCharVar('QuestCrisisMaking_var') == 1\n    then\n        -- A Crisis in the Making: Quest Objective Reminder\n        player:startEvent(262, 0, 625)\n    elseif\n        crisisstatus == xi.questStatus.QUEST_COMPLETED and\n        player:getCharVar('QuestCrisisMaking_var') == 2\n    then\n        -- A Crisis in the Making: Repeatable Quest Finish\n        player:startEvent(268)\n    else\n    --Standard dialogs\n        local rand = math.randomInt(1, 3)\n        if rand == 1 then  -- STANDARD CONVO: sings song about ingredients\n            player:startEvent(249)\n        elseif rand == 2 then   -- STANDARD CONVO 2: sings song about ingredients\n            player:startEvent(251)\n        elseif rand == 3 then   -- STANDARD CONVO 3:\n            player:startEvent(256)\n        end\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    -- A Crisis in the Making\n    if csid == 258 and option == 1 then  -- A Crisis in the Making + ITEM: Quest Offer - ACCEPTED\n        player:addQuest(xi.questLog.WINDURST, xi.quest.id.windurst.A_CRISIS_IN_THE_MAKING)\n        player:setCharVar('QuestCrisisMaking_var', 1)\n        player:needToZone(true)\n    elseif csid == 258 and option == 2 then  -- A Crisis in the Making + ITEM: Quest Offer - REFUSED\n        player:needToZone(true)\n    elseif csid == 259 and option == 1 then  -- A Crisis in the Making + ITEM: Repeatable Quest Offer - ACCEPTED\n        player:setCharVar('QuestCrisisMaking_var', 1)\n        player:needToZone(true)\n    elseif csid == 259 and option == 2 then  -- A Crisis in the Making + ITEM: Repeatable Quest Offer - REFUSED\n        player:needToZone(true)\n    elseif csid == 267 then -- A Crisis in the Making: Quest Finish\n        npcUtil.giveCurrency(player, 'gil', 400)\n        player:setCharVar('QuestCrisisMaking_var', 0)\n        player:delKeyItem(xi.keyItem.OFF_OFFERING)\n        player:addFame(xi.fameArea.WINDURST, 10)\n        player:completeQuest(xi.questLog.WINDURST, xi.quest.id.windurst.A_CRISIS_IN_THE_MAKING)\n        player:needToZone(true)\n    elseif csid == 268 then -- A Crisis in the Making: Repeatable Quest Finish\n        npcUtil.giveCurrency(player, 'gil', 400)\n        player:setCharVar('QuestCrisisMaking_var', 0)\n        player:delKeyItem(xi.keyItem.OFF_OFFERING)\n        player:addFame(xi.fameArea.WINDURST, 10)\n        player:needToZone(true)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Waters_[S]/npcs/Door_Acolyte_Hostel_up.lua"]={["Path"]="scripts/zones/Windurst_Waters_[S]/npcs/Door_Acolyte_Hostel_up.lua",["SHA256"]="3f49705319e42d6d746a34ffd7b8fe3cdf12b6ee14881acf0218e2ac009f79aa",["Text"]="-----------------------------------\n-- Area: Windurst Waters (S)\n--  NPC: Door Acolyte hostel\n-- !pos 146.619, -8.525, 242.874 94\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    if\n        player:getQuestStatus(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.SAY_IT_WITH_A_HANDBAG) == xi.questStatus.QUEST_ACCEPTED and\n        player:getCharVar('sayItWithAHandbagCS') == 0\n    then\n        player:startEvent(171)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 171 then\n        if option == 1 then\n            player:setCharVar('sayItWithAHandbagCS', 1)\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Waters_[S]/npcs/Hampu-Kampu.lua"]={["Path"]="scripts/zones/Windurst_Waters_[S]/npcs/Hampu-Kampu.lua",["SHA256"]="41753192e550f1d492f2c84662bcdde1b025a56b36db68dde17318c6a8f676a1",["Text"]="-----------------------------------\n-- Area: Windurst Waters (S)\n--  NPC: Hampu-Kampu\n-- !pos  -115.597, -1.000, -158.703 94\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local sayItWithAHandbag = player:getQuestStatus(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.SAY_IT_WITH_A_HANDBAG)\n    local sayItWithAHandbagCS = player:getCharVar('sayItWithAHandbagCS')\n\n    if sayItWithAHandbag == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(175)\n    elseif\n        player:hasKeyItem(xi.keyItem.REPAIRED_HANDBAG) and\n        sayItWithAHandbagCS == 4\n    then\n        player:startEvent(174)\n    elseif\n        player:hasKeyItem(xi.keyItem.TORN_PATCHES_OF_LEATHER) or\n        sayItWithAHandbagCS == 3\n    then\n        player:startEvent(173)\n    elseif\n        sayItWithAHandbag == xi.questStatus.QUEST_ACCEPTED and\n        sayItWithAHandbagCS == 1\n    then\n        player:startEvent(172)\n    elseif sayItWithAHandbag == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(170)\n    elseif sayItWithAHandbag == xi.questStatus.QUEST_AVAILABLE then\n        player:startEvent(169)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 174 then -- Option doesn't matter as NPC will take key item if yes or no\n        if\n            npcUtil.completeQuest(player, xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.SAY_IT_WITH_A_HANDBAG, {\n                item = 19110, -- Trainee's Needle\n                var = 'sayItWithAHandbagCS'\n            })\n        then\n            player:delKeyItem(xi.keyItem.REPAIRED_HANDBAG)\n            player:setCharVar('sayItWithAHandbagBonusCS', 1)\n        end\n    elseif csid == 172 then\n        npcUtil.giveKeyItem(player, xi.keyItem.TORN_PATCHES_OF_LEATHER)\n    elseif csid == 169 then\n        player:addQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.SAY_IT_WITH_A_HANDBAG)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Waters_[S]/npcs/Kocco_Ehllek.lua"]={["Path"]="scripts/zones/Windurst_Waters_[S]/npcs/Kocco_Ehllek.lua",["SHA256"]="d9fe578dbd1288c8f1a3e75879bcc031346170306c7aae4875d731b13465afd0",["Text"]="-----------------------------------\n-- Area: Windurst Waters (S)\n--  NPC: Kocco Ehllek\n-- Type: Quest Giver\n-- !pos -41.465 -2.125 -163.018 94\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local redeemingRocks = player:getQuestStatus(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.REDEEMING_ROCKS)\n    local rocksProg = player:getCharVar('RedeemingRocksProg')\n\n    if redeemingRocks == xi.questStatus.QUEST_AVAILABLE then\n        player:startEvent(108) -- Start quest \"Redeeming Rocks\"\n    elseif redeemingRocks == xi.questStatus.QUEST_ACCEPTED and rocksProg == 2 then\n        player:startEvent(109) -- 3rd CS quest \"Redeeming Rocks\"\n    elseif redeemingRocks == xi.questStatus.QUEST_ACCEPTED and rocksProg == 4 then\n        player:startEvent(110) -- 4th CS quest \"Redeeming Rocks\"\n    elseif\n        redeemingRocks == xi.questStatus.QUEST_ACCEPTED and\n        player:getCharVar('RedeemingDay') ~= VanadielUniqueDay()\n    then\n        player:startEvent(111) -- Last CS quest \"Redeeming Rocks\"\n    else\n        player:startEvent(140) -- Standard text\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 108 then -- Finish 'Redeeming Rocks' opening CS\n        player:addQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.REDEEMING_ROCKS)\n        player:setCharVar('RedeemingRocksProg', 1)\n    elseif csid == 109 then -- Finish 'Redeeming Rocks' third CS\n        player:setCharVar('RedeemingRocksProg', 3)\n    elseif csid == 110 then -- Finish 'Redeeming Rocks' fourth CS\n        player:setCharVar('RedeemingRocksProg', 0)\n        player:setCharVar('RedeemingDay', VanadielUniqueDay())\n    elseif csid == 111 then -- Finish 'Redeeming Rocks' quest\n        npcUtil.completeQuest(player, xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.REDEEMING_ROCKS, {\n            item = 15998,\n            var = { 'RedeemingDay' }\n        })\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Waters_[S]/npcs/Rohn_Ehlbalna.lua"]={["Path"]="scripts/zones/Windurst_Waters_[S]/npcs/Rohn_Ehlbalna.lua",["SHA256"]="c00a775a0c88514cbcdab94d0a32ceaa4fa99c18da5914b784304ea123be00db",["Text"]="-----------------------------------\n-- Area: Windurst Waters (S)\n--  NPC: Rohn Ehlbalna\n-- !pos -43.473 -4.5 46.496 94\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    if\n        player:getQuestStatus(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.REDEEMING_ROCKS) == xi.questStatus.QUEST_ACCEPTED and\n        player:getCharVar('RedeemingRocksProg') == 1\n    then\n        player:startEvent(114) -- 2nd CS quest \"Redeeming Rocks\"\n    else\n        player:startEvent(440)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 114 then -- Finish \"Redeeming Rocks\" second CS\n        player:setCharVar('RedeemingRocksProg', 2)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Woods/npcs/Apururu.lua"]={["Path"]="scripts/zones/Windurst_Woods/npcs/Apururu.lua",["SHA256"]="df19b105d6f51a90a3bfe4b1c3b30b79e1ad504439eb8b93ff3ac82a64321982",["Text"]="-----------------------------------\n-- Area: Windurst Woods\n--  NPC: Apururu\n-- Involved in Quests: The Kind Cardian, Can Cardians Cry?\n-- !pos -11 -2 13 241\n-----------------------------------\nlocal ID = zones[xi.zone.WINDURST_WOODS]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nlocal trustMemory = function(player)\n    local memories = 0\n    -- 2 - Saw him at the start of the game\n    if player:getNation() == xi.nation.WINDURST then\n        memories = memories + 2\n    end\n\n    -- 4 - WONDER_WANDS\n    if player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.WONDER_WANDS) then\n        memories = memories + 4\n    end\n\n    -- 8 - THE_TIGRESS_STIRS\n    if player:hasCompletedQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.THE_TIGRESS_STIRS) then\n        memories = memories + 8\n    end\n\n    -- 16 - I_CAN_HEAR_A_RAINBOW\n    if player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.I_CAN_HEAR_A_RAINBOW) then\n        memories = memories + 16\n    end\n\n    -- 32 - Hero's Combat (BCNM)\n    -- if (playervar for Hero's Combat) then\n    --  memories = memories + 32\n    -- end\n    -- 64 - MOON_READING\n    if player:hasCompletedMission(xi.mission.log_id.WINDURST, xi.mission.id.windurst.MOON_READING) then\n        memories = memories + 64\n    end\n\n    return memories\nend\n\nentity.onTrade = function(player, npc, trade)\n    -- THE KIND CARDIAN\n    if\n        player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.THE_KIND_CARDIAN) == xi.questStatus.QUEST_ACCEPTED and\n        npcUtil.tradeHas(trade, xi.item.TEN_OF_CUPS_CARD)\n    then\n        player:startEvent(397)\n\n        -- CAN CARDIANS CRY?\n    elseif\n        player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.CAN_CARDIANS_CRY) == xi.questStatus.QUEST_ACCEPTED and\n        npcUtil.tradeHas(trade, xi.item.BRUISED_STARFRUIT)\n    then\n        player:startEvent(325, 0, 20000, 5000)\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local kindCardian = player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.THE_KIND_CARDIAN)\n    local kindCardianCS = player:getCharVar('theKindCardianVar')\n    local allNewC3000 = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.THE_ALL_NEW_C_3000)\n    local canCardiansCry = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.CAN_CARDIANS_CRY)\n\n        -- THE KIND CARDIAN\n    if kindCardian == xi.questStatus.QUEST_ACCEPTED then\n        if kindCardianCS == 0 then\n            player:startEvent(392)\n        elseif kindCardianCS == 1 then\n            player:startEvent(393)\n        elseif kindCardianCS == 2 then\n            player:startEvent(398)\n        end\n\n        -- CAN CARDIANS CRY?\n    elseif\n        allNewC3000 == xi.questStatus.QUEST_COMPLETED and\n        canCardiansCry == xi.questStatus.QUEST_AVAILABLE and\n        player:getFameLevel(xi.fameArea.WINDURST) >= 5\n    then\n        player:startEvent(319, 0, 20000) -- start quest\n    elseif canCardiansCry == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(320, 0, 20000) -- reminder\n    elseif canCardiansCry == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(330) -- new standard dialog\n\n        -- TRUST\n    elseif\n        player:hasKeyItem(xi.keyItem.WINDURST_TRUST_PERMIT) and\n        not player:hasSpell(xi.magic.spell.AJIDO_MARUJIDO)\n    then\n        local rank6 = player:getRank(player:getNation()) >= 6 and 1 or 0\n\n        player:startEvent(866, 0, 0, 0, trustMemory(player), 0, 0, 0, rank6)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n        -- THE KIND CARDIAN\n    if csid == 392 and option == 1 then\n        player:setCharVar('theKindCardianVar', 1)\n    elseif csid == 397 then\n        player:delKeyItem(xi.keyItem.TWO_OF_SWORDS)\n        player:setCharVar('theKindCardianVar', 2)\n        player:addFame(xi.fameArea.WINDURST, 30)\n        player:confirmTrade()\n\n        -- CAN CARDIANS CRY?\n    elseif csid == 319 then\n        player:addQuest(xi.questLog.WINDURST, xi.quest.id.windurst.CAN_CARDIANS_CRY)\n    elseif\n        csid == 325 and\n        npcUtil.completeQuest(player, xi.questLog.WINDURST, xi.quest.id.windurst.CAN_CARDIANS_CRY, {\n            gil   = 5000,\n            title = xi.title.DELIVERER_OF_TEARFUL_NEWS\n        })\n    then\n        player:confirmTrade()\n\n        -- TRUST\n    elseif csid == 866 and option == 2 then\n        player:addSpell(xi.magic.spell.AJIDO_MARUJIDO, { silentLog = true })\n        player:messageSpecial(ID.text.YOU_LEARNED_TRUST, 0, xi.magic.spell.AJIDO_MARUJIDO)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Woods/npcs/Boizo-Naizo.lua"]={["Path"]="scripts/zones/Windurst_Woods/npcs/Boizo-Naizo.lua",["SHA256"]="7f67f6e5daf59fc984e665451665534c4d0438922e355f0581ac08ed5dcfa070",["Text"]="-----------------------------------\n-- Area: Windurst Woods\n--  NPC: Boizo-Naizo\n-- Involved in Quests: A Greeting Cardian, Riding on the Clouds\n-- !pos -9.581 -2.750 -26.062 241\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    if player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.THE_ALL_NEW_C_2000) == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(290)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Woods/npcs/Gioh_Ajihri.lua"]={["Path"]="scripts/zones/Windurst_Woods/npcs/Gioh_Ajihri.lua",["SHA256"]="104ecd8231249dc37c2f2ec63ee83a4448a3f810bd4ca5bf2aaf7263819c44c1",["Text"]="-----------------------------------\n-- Area: Windurst Woods\n--  NPC: Gioh Ajihri\n-- Starts & Finishes Repeatable Quest: Twinstone Bonding\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if\n        player:getCharVar('GiohAijhriSpokenTo') == 1 and\n        not player:needToZone() and\n        npcUtil.tradeHas(trade, xi.item.TWINSTONE_EARRING)\n    then\n        player:startEvent(490)\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local twinstoneBonding = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.TWINSTONE_BONDING)\n\n    if twinstoneBonding == xi.questStatus.QUEST_COMPLETED then\n        if player:needToZone() then\n            player:startEvent(491, 0, xi.item.TWINSTONE_EARRING)\n        else\n            player:startEvent(488, 0, xi.item.TWINSTONE_EARRING)\n        end\n    elseif twinstoneBonding == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(488, 0, xi.item.TWINSTONE_EARRING)\n    elseif\n        twinstoneBonding == xi.questStatus.QUEST_AVAILABLE and\n        player:getFameLevel(xi.fameArea.WINDURST) >= 2\n    then\n        player:startEvent(487, 0, xi.item.TWINSTONE_EARRING)\n    else\n        player:startEvent(424)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 487 then\n        player:addQuest(xi.questLog.WINDURST, xi.quest.id.windurst.TWINSTONE_BONDING)\n        player:setCharVar('GiohAijhriSpokenTo', 1)\n    elseif csid == 490 then\n        player:confirmTrade()\n        player:needToZone(true)\n        player:setCharVar('GiohAijhriSpokenTo', 0)\n\n        if player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.TWINSTONE_BONDING) == xi.questStatus.QUEST_ACCEPTED then\n            npcUtil.completeQuest(player, xi.questLog.WINDURST, xi.quest.id.windurst.TWINSTONE_BONDING, { item = 17154, fame = 16, fameArea = xi.fameArea.WINDURST, title = xi.title.BOND_FIXER })\n        else\n            player:addFame(xi.fameArea.WINDURST, 16)\n            npcUtil.giveCurrency(player, 'gil', 900)\n        end\n    elseif csid == 488 then\n        player:setCharVar('GiohAijhriSpokenTo', 1)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Woods/npcs/Gottah_Maporushanoh.lua"]={["Path"]="scripts/zones/Windurst_Woods/npcs/Gottah_Maporushanoh.lua",["SHA256"]="1c7995f2588d3d65cfc085c8ddc481f11d8c07d46cea2475df2fefb80484edcf",["Text"]="-----------------------------------\n-- Area: Windurst Woods\n--  NPC: Gottah Maporushanoh\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local amazinScorpio = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.THE_AMAZIN_SCORPIO)\n\n    if amazinScorpio == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(486)\n    elseif amazinScorpio == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(483)\n    else\n        player:startEvent(420)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Woods/npcs/Ibwam.lua"]={["Path"]="scripts/zones/Windurst_Woods/npcs/Ibwam.lua",["SHA256"]="34324abd1e2fef7ebc2cd0ba26c7908262b190aa4817e95377b17b2c79b198f5",["Text"]="-----------------------------------\n-- Area: Windurst Woods\n--  NPC: Ibwam\n-- Type: Warp NPC\n-- !pos -25.655 1.749 -60.651 241\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if\n        npcUtil.tradeHas(trade, { { 'gil', 300 } }) and\n        player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.LURE_OF_THE_WILDCAT) == xi.questStatus.QUEST_COMPLETED and\n        player:getCurrentMission(xi.mission.log_id.TOAU) > xi.mission.id.toau.IMMORTAL_SENTRIES\n    then\n        -- Needs a check for at least traded an invitation card to Naja Salaheem\n        player:startEvent(794)\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    if player:getCurrentMission(xi.mission.log_id.TOAU) >= xi.mission.id.toau.PRESIDENT_SALAHEEM then\n        player:startEvent(793)\n    else\n        player:startEvent(740)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 794 then\n        player:confirmTrade()\n        xi.teleport.to(player, xi.teleport.id.WHITEGATE)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Woods/npcs/Illu_Bohjaa.lua"]={["Path"]="scripts/zones/Windurst_Woods/npcs/Illu_Bohjaa.lua",["SHA256"]="dc2c6774430ccac4a90e49a3ceeb43e907a6303f7b34451987fd946f56190cd1",["Text"]="-----------------------------------\n-- Area: Windurst Woods\n--  NPC: Illu Bohjaa\n-- Involved in the repeatable quest \"Creepy Crawlies\"\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.CREEPY_CRAWLIES) ~= xi.questStatus.QUEST_AVAILABLE then\n        if npcUtil.tradeHas(trade, { { 816, 3 } }) then -- silk thread x3\n            player:addFame(xi.fameArea.WINDURST, 10)\n            player:startEvent(335, 600 * xi.settings.main.GIL_RATE, 816, 938, 1156)\n        elseif npcUtil.tradeHas(trade, { { 1156, 3 } }) then -- crawler calculus x3\n            player:addFame(xi.fameArea.WINDURST, 10)\n            player:startEvent(335, 600 * xi.settings.main.GIL_RATE, 816, 938, 1156)\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    if player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.CREEPY_CRAWLIES) == xi.questStatus.QUEST_AVAILABLE then\n        player:startEvent(333, 0, 816, 938, 1156)\n    else\n        player:startEvent(334, 0, 816, 938, 1156)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 333 and option == 1 then\n        player:addQuest(xi.questLog.WINDURST, xi.quest.id.windurst.CREEPY_CRAWLIES)\n    elseif csid == 335 then\n        player:completeQuest(xi.questLog.WINDURST, xi.quest.id.windurst.CREEPY_CRAWLIES)\n        player:addTitle(xi.title.CRAWLER_CULLER)\n        player:addGil(600 * xi.settings.main.GIL_RATE)\n        player:confirmTrade()\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Woods/npcs/Kopuro-Popuro.lua"]={["Path"]="scripts/zones/Windurst_Woods/npcs/Kopuro-Popuro.lua",["SHA256"]="900c789b9724ccce556bcbc7b52b2e3c7e2c93bcfec42dfa1eeb5afe75e4acef",["Text"]="-----------------------------------\n-- Area: Windurst Woods\n--  NPC: Kopuro-Popuro\n-- !pos -0.037 -4.749 -22.589 241\n-- Starts Quests: The All-New C-2000, Legendary Plan B, The All-New C-3000\n-- Involved in quests: Lost Chick\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    local allNewC2000 = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.THE_ALL_NEW_C_2000)\n    local legendaryPlanB = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.LEGENDARY_PLAN_B)\n    local allNewC3000 = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.THE_ALL_NEW_C_3000)\n\n    -- THE ALL NEW C-2000\n    if allNewC2000 == xi.questStatus.QUEST_ACCEPTED then\n        if npcUtil.tradeHas(trade, { 846, 856, 4368 }) then\n            player:startEvent(292, xi.settings.main.GIL_RATE * 200) -- Correct items given, complete quest.\n        else\n            player:startEvent(288, 0, 856, 846, 4368) -- Incorrect or not enough items.\n        end\n\n    -- LEGENDARY PLAN B\n    elseif legendaryPlanB == xi.questStatus.QUEST_ACCEPTED then\n        if npcUtil.tradeHas(trade, { 529, 858, 940 }) then\n            player:startEvent(314, 0, 529, 940, 858) -- Correct items given, complete quest in onEventUpdate\n        else\n            player:startEvent(309, 0, 529, 940, 858) -- Incorrect or not enough items\n        end\n\n    -- THE ALL NEW C-3000\n    elseif\n        allNewC3000 == xi.questStatus.QUEST_ACCEPTED or\n        allNewC3000 == xi.questStatus.QUEST_COMPLETED\n    then\n        if npcUtil.tradeHas(trade, { 889, 939 }) then\n            player:startEvent(657, 0, 889, 939) -- Correct items given, complete quest in onEventUpdate\n        else\n            player:startEvent(656, 0, 889, 939) -- Incorrect or not enough items\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local allNewC2000 = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.THE_ALL_NEW_C_2000)\n    local aGreetingCardian = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.A_GREETING_CARDIAN)\n    local aGreetingCardianProg = xi.quest.getVar(player, xi.questLog.WINDURST, xi.quest.id.windurst.A_GREETING_CARDIAN, 'Prog')\n    local legendaryPlanB = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.LEGENDARY_PLAN_B)\n    local allNewC3000 = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.THE_ALL_NEW_C_3000)\n\n    -- THE ALL NEW C-3000\n    if\n        legendaryPlanB == xi.questStatus.QUEST_COMPLETED and\n        allNewC3000 == xi.questStatus.QUEST_AVAILABLE and\n        player:getFameLevel(xi.fameArea.WINDURST) >= 4\n    then\n        if player:needToZone() then\n            player:startEvent(316) -- Post quest text from legendaryPlanB\n        else\n            player:startEvent(655, 0, 889, 939)\n        end\n    elseif allNewC3000 == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(659, 0, 889, 939)\n\n    -- A GREETING CARDIAN\n    elseif\n        aGreetingCardian == xi.questStatus.QUEST_ACCEPTED and\n        aGreetingCardianProg == 1\n    then\n        player:startEvent(301) -- Supplemental text when aGreetingCardian in progress, right before completion\n\n    -- LEGENDARY PLAN B\n    elseif\n        aGreetingCardian == xi.questStatus.QUEST_COMPLETED and\n        legendaryPlanB == xi.questStatus.QUEST_AVAILABLE and\n        player:getFameLevel(xi.fameArea.WINDURST) >= 3\n    then\n        if player:needToZone() then\n            player:startEvent(306) -- Supplemental text for aGreetingCardian before start of legendaryPlanB\n        else\n            player:startEvent(308, 0, 529, 940, 858) -- legendaryPlanB start\n        end\n    elseif legendaryPlanB == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(309, 0, 529, 940, 858) -- legendaryPlanB reminder\n    elseif legendaryPlanB == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(316)\n\n    -- THE ALL NEW C-2000\n    elseif allNewC2000 == xi.questStatus.QUEST_AVAILABLE then\n        player:startEvent(285, 0, 856, 846, 4368) -- Start Quest\n    elseif allNewC2000 == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(288, 0, 856, 846, 4368) -- Reminder Dialogue\n    elseif allNewC2000 == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(293) -- Post Quest Finish Text\n\n    -- STANDARD DIALOG\n    else\n        player:startEvent(276)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    -- THE ALL NEW C-2000\n    if csid == 285 and option ~= 2 then  -- option 2 is declining the quest for the second question\n        player:addQuest(xi.questLog.WINDURST, xi.quest.id.windurst.THE_ALL_NEW_C_2000)\n    elseif csid == 292 then\n        player:completeQuest(xi.questLog.WINDURST, xi.quest.id.windurst.THE_ALL_NEW_C_2000)\n        player:addFame(xi.fameArea.WINDURST, 20)\n        player:addTitle(xi.title.CARDIAN_TUTOR)\n        player:addGil(xi.settings.main.GIL_RATE * 200)\n        player:confirmTrade()\n\n    -- LEGENDARY PLAN B\n    elseif csid == 308 then\n        player:addQuest(xi.questLog.WINDURST, xi.quest.id.windurst.LEGENDARY_PLAN_B)\n    elseif\n        csid == 314 and\n        npcUtil.completeQuest(player, xi.questLog.WINDURST, xi.quest.id.windurst.LEGENDARY_PLAN_B, { item = xi.item.SCENTLESS_ARMLETS, gil = 700, fame = 30, fameArea = xi.fameArea.WINDURST })\n    then\n        player:confirmTrade()\n        player:needToZone(true)\n\n    -- THE ALL NEW C-3000\n    elseif csid == 655 then\n        player:addQuest(xi.questLog.WINDURST, xi.quest.id.windurst.THE_ALL_NEW_C_3000)\n    elseif\n        csid == 657 and\n        npcUtil.completeQuest(player, xi.questLog.WINDURST, xi.quest.id.windurst.THE_ALL_NEW_C_3000, { fame = 40, gil = 600 })\n    then\n        player:confirmTrade()\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Woods/npcs/Kororo.lua"]={["Path"]="scripts/zones/Windurst_Woods/npcs/Kororo.lua",["SHA256"]="93664903a17187ac245b70de63e6755bc5973f1193a954380553d17e059b1b86",["Text"]="-----------------------------------\n-- Area: Windurst Woods\n--  NPC: Kororo\n-- !pos -11.883 -2.750 5.508 241\n-- Involved in Quests: A Greeting Cardian, Lost Chick\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local c2000 = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.THE_ALL_NEW_C_2000)\n    local lpb   = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.LEGENDARY_PLAN_B)\n\n    if c2000 == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(291)\n\n    -- Might be Legendary Plan B, most likely Lost Chick related.\n    -- only activates before LPB completes so leaving it in as is for now\n    elseif lpb == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(312, 0, 529, 940, 858)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Woods/npcs/Kuoh_Rhel.lua"]={["Path"]="scripts/zones/Windurst_Woods/npcs/Kuoh_Rhel.lua",["SHA256"]="612b1e049ac4f5c297703fb264f71879d7caf8a413c19f4334d3fd6962bfacbe",["Text"]="-----------------------------------\n-- Area: Windurst Woods\n--  NPC: Kuoh Rhel\n-- Starts quests: Chocobilious, In a Stew\n-- !pos 131.437 -6 -102.723 241\n--  Note: In a Stew should only repeat once per conquest tally. The tally is not implemented at time of\n--        writing this quest. Once it is working please feel free to add it in ^^\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local chocobilious = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.CHOCOBILIOUS)\n\n    -- CHOCOBILIOUS\n    if\n        chocobilious == xi.questStatus.QUEST_AVAILABLE and\n        player:getFameLevel(xi.fameArea.WINDURST) >= 2\n    then\n        player:startEvent(224) -- Start quest\n    elseif chocobilious == xi.questStatus.QUEST_COMPLETED and player:needToZone() then\n        player:startEvent(232) -- Quest complete\n    elseif\n        chocobilious == xi.questStatus.QUEST_ACCEPTED and\n        player:getCharVar('ChocobiliousQuest') == 2\n    then\n        player:startEvent(231) -- Talked to Tapoh\n    elseif chocobilious == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(225) -- Post quest accepted\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    -- CHOCOBILIOUS\n    if csid == 224 and option == 1 then\n        player:addQuest(xi.questLog.WINDURST, xi.quest.id.windurst.CHOCOBILIOUS)\n    elseif\n        csid == 231 and\n        npcUtil.completeQuest(player, xi.questLog.WINDURST, xi.quest.id.windurst.CHOCOBILIOUS, { fame = 20, fameArea = xi.fameArea.WINDURST, gil = 1500, var = 'ChocobiliousQuest' })\n    then\n        player:needToZone(true)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Woods/npcs/Matata.lua"]={["Path"]="scripts/zones/Windurst_Woods/npcs/Matata.lua",["SHA256"]="8cfa8e0326427a70aad3efb0fbac67af4b0b427cc55c246206f4f8e635967bc0",["Text"]="-----------------------------------\n-- Area: Windurst Woods\n--  NPC: Matata\n-- Involved in quest: In a Stew\n-- !pos 131 -5 -109 241\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local chocobilious = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.CHOCOBILIOUS)\n\n    -- CHOCOBILIOUS\n    if chocobilious == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(226) -- Chocobilious complete\n\n    -- STANDARD DIALOG\n    else\n        player:startEvent(223)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Woods/npcs/Mheca_Khetashipah.lua"]={["Path"]="scripts/zones/Windurst_Woods/npcs/Mheca_Khetashipah.lua",["SHA256"]="1f1441834b94d328140396095750680d9afbc94070f8f179dec14bf482bc1705",["Text"]="-----------------------------------\n-- Area: Windurst Woods\n--  NPC: Mheca Khetashipah\n-- !pos 66.881 -6.249 185.752 241\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local starStatus = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.MIHGOS_AMIGO)\n\n    if starStatus == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(83)\n    else\n        -- Possibly not their default dialogue. Event #79 witnessed in capture. Leaving for now until\n        -- verified.\n        player:startEvent(426)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Woods/npcs/Nanaa_Mihgo.lua"]={["Path"]="scripts/zones/Windurst_Woods/npcs/Nanaa_Mihgo.lua",["SHA256"]="48847a501bc3ca7085ec0e5a4e39fc421f9584ac5200b2ab435a26d0f6dfaf4e",["Text"]="-----------------------------------\n-- Area: Windurst Walls\n--  NPC: Nanaa Mihgo\n-- Starts and Finishes Quest: Mihgo's Amigo (R), The Tenshodo Showdown (start), Rock Racketeer (start)\n-- Involved In Quest: Crying Over Onions\n-- Involved in Mission 2-1\n-- !pos 62 -4 240 241\n-----------------------------------\nlocal ID = zones[xi.zone.WINDURST_WOODS]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nlocal trustMemory = function(player)\n    local memories = 0\n    -- 2 - Saw her at the start of the game\n    if player:getNation() == xi.nation.WINDURST then\n        memories = memories + 2\n    end\n\n    -- 4 - ROCK_RACKETEER\n    if player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.ROCK_RACKETEER) then\n        memories = memories + 4\n    end\n\n    -- 8 - HITTING_THE_MARQUISATE\n    if player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.HITTING_THE_MARQUISATE) then\n        memories = memories + 8\n    end\n\n    -- 16 - CRYING_OVER_ONIONS\n    if player:hasCompletedQuest(xi.questLog.WINDURST, xi.quest.id.windurst.CRYING_OVER_ONIONS) then\n        memories = memories + 16\n    end\n\n    -- 32 - hasItem(286) Nanaa Mihgo statue\n    if player:hasItem(xi.item.NANAA_MIHGO_STATUE) then\n        memories = memories + 32\n    end\n\n    -- 64 - ROAR_A_CAT_BURGLAR_BARES_HER_FANGS\n    if player:hasCompletedMission(xi.mission.log_id.AMK, xi.mission.id.amk.ROAR_A_CAT_BURGLAR_BARES_HER_FANGS) then\n        memories = memories + 64\n    end\n\n    return memories\nend\n\nentity.onTrigger = function(player, npc)\n    local mihgosAmigo = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.MIHGOS_AMIGO)\n\n    -- TRUST\n    if\n        player:hasKeyItem(xi.keyItem.WINDURST_TRUST_PERMIT) and\n        not player:hasSpell(xi.magic.spell.NANAA_MIHGO) and\n        player:getLocalVar('TrustDialogue') == 0\n    then\n        local trustFlag = (player:getRank(player:getNation()) >= 3 and 1 or 0) + (mihgosAmigo == xi.questStatus.QUEST_COMPLETED and 2 or 0)\n\n        player:setLocalVar('TrustDialogue', 1)\n\n        player:startEvent(865, 0, 0, 0, trustMemory(player), 0, 0, 0, trustFlag)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 865 and option == 2 then\n        player:addSpell(xi.magic.spell.NANAA_MIHGO, { silentLog = true })\n        player:messageSpecial(ID.text.YOU_LEARNED_TRUST, 0, xi.magic.spell.NANAA_MIHGO)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Woods/npcs/Perih_Vashai.lua"]={["Path"]="scripts/zones/Windurst_Woods/npcs/Perih_Vashai.lua",["SHA256"]="af77992d9bbc320c5bbb4114add7c7f0c03373e9c7578178456949be9d552c0b",["Text"]="-----------------------------------\n-- Area: Windurst Woods\n--  NPC: Perih Vashai\n-- Involved in Quests: Sin Hunting (RNG AF1), Fire and Brimstone (RNG AF2), Unbridled Passion (RNG AF3)\n-- !pos 117 -3 92 241\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    -- FIRE AND BRIMSTONE\n    if\n        player:getCharVar('fireAndBrimstone') == 5 and\n        npcUtil.tradeHas(trade, xi.item.OLD_EARRING)\n    then\n        -- old earring\n        player:startEvent(537, 0, 13360)\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local sinHunting = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.SIN_HUNTING)-- RNG AF1\n    local fireAndBrimstone = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.FIRE_AND_BRIMSTONE)-- RNG AF2\n    local fireAndBrimstoneCS = player:getCharVar('fireAndBrimstone')\n    local unbridledPassion = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.UNBRIDLED_PASSION)-- RNG AF3\n    local unbridledPassionCS = player:getCharVar('unbridledPassion')\n    local lvl = player:getMainLvl()\n    local job = player:getMainJob()\n\n    -- FIRE AND BRIMSTONE\n    if\n        sinHunting == xi.questStatus.QUEST_COMPLETED and\n        job == xi.job.RNG and\n        lvl >= xi.settings.main.AF2_QUEST_LEVEL and\n        fireAndBrimstone == xi.questStatus.QUEST_AVAILABLE\n    then\n        player:startEvent(531) -- start RNG AF2\n    elseif\n        sinHunting == xi.questStatus.QUEST_COMPLETED and\n        fireAndBrimstone == xi.questStatus.QUEST_AVAILABLE\n    then\n        player:startEvent(528) -- after RNG AF1, before starting RNG AF2\n    elseif fireAndBrimstoneCS > 0 and fireAndBrimstoneCS < 4 then\n        player:startEvent(532) -- during RNG AF2\n    elseif fireAndBrimstoneCS == 4 then\n        player:startEvent(535, 0, 13360, xi.item.OLD_EARRING) -- second part RNG AF2\n    elseif fireAndBrimstoneCS == 5 then\n        player:startEvent(536, 0, 13360, xi.item.OLD_EARRING) -- during second part RNG AF2\n\n    -- UNBRIDLED PASSION\n    elseif\n        fireAndBrimstone == xi.questStatus.QUEST_COMPLETED and\n        job == xi.job.RNG and\n        lvl >= xi.settings.main.AF3_QUEST_LEVEL and\n        unbridledPassion == xi.questStatus.QUEST_AVAILABLE\n    then\n        player:startEvent(541, 0, 13360) -- start RNG AF3\n    elseif unbridledPassionCS > 0 and unbridledPassionCS < 7 then\n        player:startEvent(542)-- during RNG AF3\n    elseif unbridledPassionCS == 7 then\n        player:startEvent(546, 0, 14099) -- complete RNG AF3\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    -- FIRE AND BRIMSTONE\n    if csid == 531 then -- start RNG AF2\n        player:addQuest(xi.questLog.WINDURST, xi.quest.id.windurst.FIRE_AND_BRIMSTONE)\n        player:setCharVar('fireAndBrimstone', 1)\n    elseif csid == 535 then -- start second part RNG AF2\n        player:setCharVar('fireAndBrimstone', 5)\n    elseif\n        csid == 537 and\n        npcUtil.completeQuest(player, xi.questLog.WINDURST, xi.quest.id.windurst.FIRE_AND_BRIMSTONE, { item = 12518, fame = 20, fameArea = xi.fameArea.WINDURST, var = 'fireAndBrimstone' })\n    then\n        -- complete quest RNG AF2\n        player:confirmTrade()\n\n    -- UNBRIDLED PASSION\n    elseif csid == 541 then -- start RNG AF3\n        player:addQuest(xi.questLog.WINDURST, xi.quest.id.windurst.UNBRIDLED_PASSION)\n        player:setCharVar('unbridledPassion', 1)\n    elseif\n        csid == 546 and\n        npcUtil.completeQuest(player, xi.questLog.WINDURST, xi.quest.id.windurst.UNBRIDLED_PASSION, { item = 14099, fame = 20, fameArea = xi.fameArea.WINDURST, var = 'unbridledPassion' })\n    then\n        -- complete quest RNG AF3\n        player:delKeyItem(xi.keyItem.KOHS_LETTER)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Woods/npcs/Ponono.lua"]={["Path"]="scripts/zones/Windurst_Woods/npcs/Ponono.lua",["SHA256"]="0b3172ad629f7c290114e6c8c1ed87b88a9bde06878d77dfd186a772ae0c700d",["Text"]="-----------------------------------\n-- Area: Windurst Woods\n--  NPC: Ponono\n-- Type: Clothcraft Guild Master\n-- !pos -38.243 -2.25 -120.954 241\n-- TODO Allow players to purchase additional Cuttings\n-- TODO Allow players to cancel quest\n-- TODO Requre check for other 3 quests An Understanding General, A Generous General,\n-- TODO: Convert this quest to interaction.\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    local moralManifest = player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.A_MORAL_MANIFEST)\n\n    if\n        moralManifest == xi.questStatus.QUEST_ACCEPTED and\n        player:getCharVar('moral') == 2 and\n        npcUtil.tradeHas(trade, { 828, 830, { 'gil', 10000 } }) -- Trade Velvet Cloth, Rainbow Cloth and 10k\n    then\n        player:setCharVar('moral', 3)\n        player:setLocalVar('moralZone', 1)\n        player:setCharVar('moralWait', getVanaMidnight())\n        player:startEvent(703)\n\n    else\n        xi.crafting.guildMasterOnTrade(player, npc, trade)\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local moralManifest = player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.A_MORAL_MANIFEST)\n\n    -- TODO: Convert this to interaction. The way this is coded, it WILL block you out from a guildmaster.\n    if\n        moralManifest == xi.questStatus.QUEST_ACCEPTED and\n        player:getCharVar('moral') == 1\n    then\n        player:startEvent(700)\n\n    elseif\n        moralManifest == xi.questStatus.QUEST_COMPLETED or\n        moralManifest == xi.questStatus.QUEST_ACCEPTED and\n        player:getCharVar('moral') >= 4\n    then\n        player:startEvent(704)\n\n    elseif\n        player:getCharVar('moral') == 3 and\n        player:getLocalVar('moralZone') == 0 and\n        player:getCharVar('moralWait') <= GetSystemTime()\n    then\n        player:startEvent(705)\n\n    -- Regular guildmaster logic.\n    else\n        xi.crafting.guildMasterOnTrigger(player, npc)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 700 then\n        player:setCharVar('moral', 2)\n    elseif csid == 705 then\n        if npcUtil.giveItem(player, xi.item.YAGUDO_HEADDRESS_CUTTING) then\n            player:setCharVar('moral', 4)\n        end\n    else\n        xi.crafting.guildMasterOnEventFinish(player, csid, option, npc)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Windurst_Woods/npcs/Soni-Muni.lua"]={["Path"]="scripts/zones/Windurst_Woods/npcs/Soni-Muni.lua",["SHA256"]="3664bbf7d2625ddafab06e2a5b0197c2dcf97f89b2ab75769b6a83c3409c6e09",["Text"]="-----------------------------------\n-- Area: Windurst Woods\n--  NPC: Soni-Muni\n-- Starts & Finishes Quest: The Amazin' Scorpio\n-- !pos -17.073 1.749 -59.327 241\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nlocal pathNodes =\n{\n    { x = -18.366, y = 1.750, z = -59.804, wait = 8000 },\n    { x = -18.303, y = 1.750, z = -59.925 },\n    { x = -18.176, y = 1.750, z = -59.733 },\n    { x = -17.620, y = 1.750, z = -59.529 },\n    { x = -16.961, y = 1.750, z = -59.286 },\n    { x = -16.590, y = 1.750, z = -59.149, wait = 8000 },\n    { x = -16.961, y = 1.750, z = -59.286 },\n    { x = -17.620, y = 1.750, z = -59.529 },\n    { x = -18.176, y = 1.750, z = -59.733 },\n    { x = -18.303, y = 1.750, z = -59.925 },\n}\n\nentity.onSpawn = function(npc)\n    npc:initNpcAi()\n    npc:setPos(xi.path.first(pathNodes))\n    npc:pathThrough(pathNodes, xi.path.flag.PATROL)\nend\n\nentity.onTrade = function(player, npc, trade)\n    if\n        player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.THE_AMAZIN_SCORPIO) == xi.questStatus.QUEST_ACCEPTED and\n        npcUtil.tradeHas(trade, xi.item.SCORPION_STINGER)\n    then\n        player:startEvent(484)\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local amazinScorpio = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.THE_AMAZIN_SCORPIO)\n\n    if amazinScorpio == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(485)\n    elseif amazinScorpio == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(482, 0, 0, xi.item.SCORPION_STINGER)\n    elseif\n        amazinScorpio == xi.questStatus.QUEST_AVAILABLE and\n        player:getFameLevel(xi.fameArea.WINDURST) >= 2\n    then\n        player:startEvent(481, 0, 0, xi.item.SCORPION_STINGER)\n    else\n        player:startEvent(421)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 481 then\n        player:addQuest(xi.questLog.WINDURST, xi.quest.id.windurst.THE_AMAZIN_SCORPIO)\n    elseif\n        csid == 484 and\n        npcUtil.completeQuest(player, xi.questLog.WINDURST, xi.quest.id.windurst.THE_AMAZIN_SCORPIO, { fame = 20, fameArea = xi.fameArea.WINDURST, title = xi.title.GREAT_GRAPPLER_SCORPIO, gil = 1500 })\n    then\n        player:confirmTrade()\n    end\nend\n\nreturn entity\n"}};
